Account original = new Account(Id = '001B000001DVM9tIAH', Name = 'Acme');
List<Account> accounts = new List<Account>{original};
List<Account> preserved = accounts.deepClone(true, true, true);
List<Account> cleared = accounts.deepClone(false, false, false);
Account preservedAccount = preserved.get(0);
preservedAccount.Name = 'Clone';
System.assertEquals(original.Id, preserved.get(0).Id);
System.assertEquals(null, cleared.get(0).Id);
System.assertEquals('Acme', original.Name);
System.assertEquals('Clone', preserved.get(0).Name);
